'use strict';
const doctors=[{id:'doc1',name:'Dr. Richard James',specialty:'general',experience:'٤ سنوات'},{id:'doc2',name:'Dr. Emily Larson',specialty:'gynecology',experience:'٣ سنوات'},{id:'doc3',name:'Dr. Sarah Patel',specialty:'dermatology',experience:'سنة واحدة'},{id:'doc4',name:'Dr. Christopher Lee',specialty:'pediatrics',experience:'سنتان'},{id:'doc5',name:'Dr. Jennifer Garcia',specialty:'neurology',experience:'٤ سنوات'},{id:'doc14',name:'Dr. Ryan Martinez',specialty:'gynecology',experience:'٣ سنوات'}];
const specialties=[{id:'general',name:'طب عام',image:'General_physician.svg'},{id:'gynecology',name:'نساء وتوليد',image:'Gynecologist.svg'},{id:'dermatology',name:'جلدية',image:'Dermatologist.svg'},{id:'pediatrics',name:'أطفال',image:'Pediatricians.svg'},{id:'neurology',name:'مخ وأعصاب',image:'Neurologist.svg'}];
const times=['09:00','10:00','11:30','13:00','14:30','16:00','17:00','18:30'];const storageKey='zb-showcase-prescripto-v1';const $=id=>document.getElementById(id);const esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));const specialtyName=id=>specialties.find(s=>s.id===id).name;
let filter='all',bookings=[],selectedDoctor=null,selectedDay='',selectedTime='';
try{const saved=JSON.parse(localStorage.getItem(storageKey));if(Array.isArray(saved)&&saved.length<100&&saved.every(b=>b&&doctors.some(d=>d.id===b.doctor)&&/^\d{4}-\d{2}-\d{2}$/.test(b.day)&&times.includes(b.time)&&typeof b.id==='string'))bookings=saved;}catch{}
const dateKey=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const days=Array.from({length:5},(_,index)=>{const date=new Date();date.setHours(12,0,0,0);date.setDate(date.getDate()+index+1);return{key:dateKey(date),label:date.toLocaleDateString('ar-EG',{weekday:'short'}),number:new Intl.NumberFormat('ar-EG').format(date.getDate())};});
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),3200);}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(bookings));}catch{toast('الحجز متاح في هذه الجلسة؛ المتصفح لا يسمح بالحفظ المحلي.');}}
function renderDoctors(){const query=$('doctorSearch').value.toLowerCase().trim();$('specialties').innerHTML=`<button type="button" class="specialty" data-specialty="all" aria-pressed="${filter==='all'}">كل التخصصات</button>`+specialties.map(s=>`<button type="button" class="specialty" data-specialty="${s.id}" aria-pressed="${filter===s.id}"><img src="assets/${s.image}" alt="">${s.name}</button>`).join('');const visible=doctors.filter(d=>(filter==='all'||d.specialty===filter)&&d.name.toLowerCase().includes(query));$('doctors').innerHTML=visible.map(d=>`<article class="doctor-card"><div class="doctor-photo"><img src="assets/${d.id}.png" alt="صورة توضيحية للطبيب ${esc(d.name)}" loading="lazy"></div><div class="doctor-copy"><span class="available">مواعيد توضيحية متاحة</span><h3>${esc(d.name)}</h3><p>${specialtyName(d.specialty)}</p><div class="doctor-bottom"><span>خبرة: ${d.experience}</span><button type="button" data-book="${d.id}" aria-label="حجز تجريبي مع ${esc(d.name)}">اختر موعدًا ←</button></div></div></article>`).join('');$('noDoctors').hidden=visible.length>0;}
function renderBookings(){$('bookingCount').textContent=new Intl.NumberFormat('ar-EG').format(bookings.length);$('bookingList').innerHTML=bookings.length?bookings.slice().sort((a,b)=>(a.day+a.time).localeCompare(b.day+b.time)).map(b=>{const doctor=doctors.find(d=>d.id===b.doctor);const day=new Date(b.day+'T12:00:00').toLocaleDateString('ar-EG',{weekday:'long',day:'numeric',month:'long'});return `<article class="booking-item"><img src="assets/${doctor.id}.png" alt=""><div class="booking-info"><strong>${esc(doctor.name)}</strong><p>${specialtyName(doctor.specialty)} · ${esc(day)} · <bdi>${b.time}</bdi></p><p>حجز توضيحي محفوظ محليًا</p></div><button type="button" class="cancel-button" data-cancel="${esc(b.id)}" aria-label="إلغاء الحجز التجريبي مع ${esc(doctor.name)}">إلغاء الحجز</button></article>`;}).join(''):'<p class="empty">لا توجد حجوزات تجريبية بعد. اختر طبيبًا وموعدًا لتجربة رحلة الحجز.</p>';}
function isBooked(time){return bookings.some(b=>b.doctor===selectedDoctor.id&&b.day===selectedDay&&b.time===time);}
function renderSlots(){if(selectedTime&&isBooked(selectedTime))selectedTime='';$('days').innerHTML=days.map(day=>`<button type="button" class="day" data-day="${day.key}" aria-pressed="${selectedDay===day.key}">${day.label}<span>${day.number}</span></button>`).join('');$('slots').innerHTML=times.map(time=>`<button type="button" class="slot" data-time="${time}" aria-pressed="${selectedTime===time}" ${isBooked(time)?'disabled':''} aria-label="${time}${isBooked(time)?'، محجوز في المعاينة':''}">${time}</button>`).join('');$('confirmBooking').disabled=!selectedTime;}
function openBooking(id){selectedDoctor=doctors.find(d=>d.id===id);selectedDay=days[0].key;selectedTime='';$('selectedDoctor').innerHTML=`<img src="assets/${selectedDoctor.id}.png" alt=""><div><p class="eyebrow">حجز توضيحي</p><h2>${esc(selectedDoctor.name)}</h2><p>${specialtyName(selectedDoctor.specialty)} · خبرة ${selectedDoctor.experience}</p></div>`;renderSlots();$('bookingDialog').showModal();}
$('specialties').addEventListener('click',event=>{const button=event.target.closest('[data-specialty]');if(button){filter=button.dataset.specialty;renderDoctors();}});$('doctorSearch').addEventListener('input',renderDoctors);$('doctors').addEventListener('click',event=>{const button=event.target.closest('[data-book]');if(button)openBooking(button.dataset.book);});$('days').addEventListener('click',event=>{const button=event.target.closest('[data-day]');if(button){selectedDay=button.dataset.day;selectedTime='';renderSlots();}});$('slots').addEventListener('click',event=>{const button=event.target.closest('[data-time]');if(button&&!button.disabled){selectedTime=button.dataset.time;renderSlots();}});$('closeBooking').addEventListener('click',()=>$('bookingDialog').close());
$('bookingForm').addEventListener('submit',event=>{event.preventDefault();if(!selectedTime||isBooked(selectedTime))return toast('اختر موعدًا توضيحيًا متاحًا.');if(bookings.length>=99)return toast('وصلت المعاينة إلى حد الحجوزات. امسح الحجوزات لبدء تجربة جديدة.');bookings.push({id:'demo-'+Date.now(),doctor:selectedDoctor.id,day:selectedDay,time:selectedTime});persist();renderBookings();$('bookingDialog').close();toast('تم حفظ الحجز التجريبي في هذا المتصفح.');});
$('bookingList').addEventListener('click',event=>{const button=event.target.closest('[data-cancel]');if(!button)return;bookings=bookings.filter(b=>b.id!==button.dataset.cancel);persist();renderBookings();toast('تم إلغاء الحجز التجريبي.');});$('resetBookings').addEventListener('click',()=>{bookings=[];persist();renderBookings();toast('تم مسح الحجوزات التجريبية.');});renderDoctors();renderBookings();
